function lecture(id, skillId, objectives, sections, workedExamples, misconceptions, checks, assets = []) {
  return { id, skillId, objectives, sections, workedExamples, misconceptions, checks, assets };
}

function question(id, skillId, difficulty, stem, options, answerIndex, reasons, reviews, cognitiveProcess, representationType, misconceptionTargets, assets = [], stimulusId) {
  return { id, skillId, difficulty, stem, options, answerIndex, reasons, reviews, cognitiveProcess, representationType, misconceptionTargets, assets, ...(stimulusId ? { stimulusId } : {}) };
}

function stimulus(id, skillId, type, label, blocks, plainText, longDescription, assets = []) {
  return {
    id,
    skillId,
    type,
    content: { label, blocks, sourceNote: "本站原創史料情境，依官方課綱與會考題型重新撰寫，未複製歷屆試題文字。" },
    accessibility: { plainText, longDescription },
    assets,
  };
}

